package ru.folio.notes;

import android.graphics.*;

/** Graphite alloy, silver edges and violet details match the physical pen textures. */
final class GuideArt {
    static void arm(Canvas c,Paint p,float x,float y,float z,float w,float thickness){c.save();c.translate(x,y);c.rotate((float)Math.toDegrees(Math.atan2(w-y,z-x)));float length=Ink.dist(x,y,z,w);p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,-thickness,0,thickness,new int[]{0xff13151b,0xff606672,0xff272c35,0xff101218},null,Shader.TileMode.CLAMP));c.drawRoundRect(0,-thickness/2,length,thickness/2,thickness/3,thickness/3,p);p.setShader(null);p.setStrokeWidth(thickness*.09f);p.setColor(0xffa7abb6);c.drawLine(3,-thickness*.27f,length-3,-thickness*.27f,p);p.setColor(0xff171a21);p.setStrokeWidth(thickness*.12f);for(float t=length*.3f;t<length*.7f;t+=thickness*.6f)c.drawLine(t,-thickness*.1f,t,thickness*.2f,p);c.restore();}
    static void compass(Canvas c,float x,float y,float size,int accent){c.save();c.translate(x-size/2,y-size/2);c.scale(size/64,size/64);Paint p=new Paint(3);p.setColor(0x33000000);c.drawOval(6,55,60,62,p);arm(c,p,32,16,12,55,7);arm(c,p,32,16,52,55,8);p.setColor(0xffc6cbd4);Path needle=new Path();needle.moveTo(9,51);needle.lineTo(11,63);needle.lineTo(15,53);needle.close();c.drawPath(needle,p);p.setColor(accent);c.drawRoundRect(47,46,54,54,2,2,p);p.setColor(0xff191b23);c.drawCircle(32,16,9,p);p.setShader(new LinearGradient(23,10,41,22,0xffd3d7df,0xff515764,Shader.TileMode.CLAMP));c.drawCircle(32,16,6.8f,p);p.setShader(null);p.setColor(0xff232730);c.drawCircle(32,16,3,p);p.setStrokeWidth(1);p.setColor(0xffe4e7ee);c.drawLine(29,18,35,14,p);p.setColor(0xff333946);c.drawRoundRect(28,0,36,9,2,2,p);p.setColor(accent);c.drawRect(28,4,36,5,p);p.setColor(0xffadb2c0);p.setStrokeWidth(1.2f);c.drawLine(20,37,45,37,p);p.setColor(accent);c.drawCircle(32,37,3,p);c.restore();}
    static Bitmap icon(){Bitmap b=Bitmap.createBitmap(192,192,Bitmap.Config.ARGB_8888);compass(new Canvas(b),96,96,182,Studio.ACCENT);return b;}
    static void overlay(Canvas c,float x,float y,float ex,float ey,float radius,float pixel){Paint p=new Paint(3);float jx=(x+ex)/2,jy=(y+ey)/2-radius*.6f;arm(c,p,jx,jy,x,y,6*pixel);arm(c,p,jx,jy,ex,ey,7*pixel);p.setShader(new LinearGradient(jx-6*pixel,jy,jx+6*pixel,jy,0xffd3d7df,0xff505766,Shader.TileMode.CLAMP));c.drawCircle(jx,jy,7*pixel,p);p.setShader(null);p.setColor(0xff252833);c.drawCircle(jx,jy,3*pixel,p);p.setColor(Studio.ACCENT);c.drawCircle(ex,ey,3*pixel,p);p.setColor(0xffcbd0dc);c.drawCircle(x,y,2*pixel,p);}
}
